function tryLockLandscape() {
  try {
    const el = document.documentElement;
    const req = el.requestFullscreen || el.webkitRequestFullscreen || el.mozRequestFullScreen;
    if (req) {
      req.call(el).then(() => {
        if (screen.orientation && screen.orientation.lock) {
          screen.orientation.lock('landscape').catch(()=>{});
        }
      }).catch(()=>{});
    } else if (screen.orientation && screen.orientation.lock) {
      screen.orientation.lock('landscape').catch(()=>{});
    }
  } catch(e){}
}

function fullscreenElement() {
  return document.fullscreenElement || document.webkitFullscreenElement || document.mozFullScreenElement || document.msFullscreenElement || null;
}
function getFullscreenRequest(el) {
  return el.requestFullscreen || el.webkitRequestFullscreen || el.webkitRequestFullScreen || el.mozRequestFullScreen || el.msRequestFullscreen || null;
}
function fullscreenSupported() {
  return !!(getFullscreenRequest(document.documentElement) || getFullscreenRequest(document.body));
}
function exitFullscreenSafe() {
  try {
    const exit = document.exitFullscreen || document.webkitExitFullscreen || document.webkitCancelFullScreen || document.mozCancelFullScreen || document.msExitFullscreen;
    if (!exit) return;
    const p = exit.call(document);
    if (p && typeof p.catch === 'function') p.catch(function(){});
  } catch (e) {}
}
function lockLandscapeSafe() {
  try {
    if (screen.orientation && screen.orientation.lock) {
      screen.orientation.lock('landscape').catch(function(){});
    }
  } catch (e) {}
}
function updateFsToggleLabel() {
  const btn = document.getElementById('fsToggleBtn');
  if (!btn) return;
  btn.textContent = fullscreenElement() ? 'EXIT FULLSCREEN' : 'FULLSCREEN';
}
function tryLockLandscape() {
  /* User-gesture fullscreen; never block play on failure (iOS Safari has no FS API). */
  try {
    const container = document.getElementById('gameContainer');
    const candidates = [container, document.documentElement, document.body].filter(Boolean);
    let req = null, target = null;
    for (let i = 0; i < candidates.length; i++) {
      req = getFullscreenRequest(candidates[i]);
      if (req) { target = candidates[i]; break; }
    }
    if (!req || !target) {
      lockLandscapeSafe();
      return Promise.resolve(false);
    }
    let p = null;
    try {
      p = req.call(target, { navigationUI: 'hide' });
    } catch (e1) {
      try { p = req.call(target); } catch (e2) { p = null; }
    }
    const afterOk = function () {
      lockLandscapeSafe();
      updateFsToggleLabel();
      settleFullscreenLayout();
      return true;
    };
    if (p && typeof p.then === 'function') {
      return p.then(afterOk).catch(function () { lockLandscapeSafe(); settleFullscreenLayout(); return false; });
    }
    afterOk();
    return Promise.resolve(true);
  } catch (e) {
    return Promise.resolve(false);
  }
}
function maybeShowA2HSHint() {
  try {
    const standalone = (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches)
      || window.navigator.standalone === true;
    if (standalone) return;
    if (localStorage.getItem('hoc_a2hs_dismissed') === '1') return;
    if (fullscreenSupported()) return;
    if (isPortraitTouch()) return;
    const hint = document.getElementById('a2hsHint');
    if (hint) hint.classList.add('show');
  } catch (e) {}
}
function setupFullscreenUi() {
  const btn = document.getElementById('fsToggleBtn');
  if (btn) {
    if (fullscreenSupported()) btn.classList.add('show');
    btn.addEventListener('click', function (e) {
      e.preventDefault();
      if (fullscreenElement()) exitFullscreenSafe();
      else tryLockLandscape();
      setTimeout(updateFsToggleLabel, 250);
      settleFullscreenLayout();
    });
  }
  const dismiss = document.getElementById('a2hsDismiss');
  if (dismiss) {
    dismiss.addEventListener('click', function () {
      localStorage.setItem('hoc_a2hs_dismissed', '1');
      const hint = document.getElementById('a2hsHint');
      if (hint) hint.classList.remove('show');
    });
  }
  ['fullscreenchange','webkitfullscreenchange','mozfullscreenchange','MSFullscreenChange'].forEach(function (ev) {
    document.addEventListener(ev, function () {
      updateFsToggleLabel();
      settleFullscreenLayout();
    });
  });
  updateFsToggleLabel();
}

document.getElementById('playBtn').addEventListener('click',()=>{
  getAudioCtx();
  if (isPortraitTouch()) { applyPortraitLock(); return; }
  const fsP = tryLockLandscape();
  maybeShowA2HSHint();
  startGame();
  if (fsP && typeof fsP.then === 'function') fsP.then(function () { settleFullscreenLayout(); });
  else settleFullscreenLayout();
});

function startGame() {
  tryLockLandscape();
  document.getElementById('portraitOverlay').classList.add('dismissed');
  switchScreen('game'); initGame(); lastTime=0; startBgAudio();
  if (animId) cancelAnimationFrame(animId);
  animId=requestAnimationFrame(gameLoop);
  runCountdown();
}

function startGame() {
  if (isPortraitTouch()) {
    applyPortraitLock();
    return; /* never start / never dismiss overlay in portrait on touch */
  }
  const fsP = tryLockLandscape();
  maybeShowA2HSHint();
  document.getElementById('portraitOverlay').classList.add('dismissed');
  window.__hocPortraitLocked = false;
  switchScreen('game'); initGame(); lastTime=0; startBgAudio();
  if (animId) cancelAnimationFrame(animId);
  animId=requestAnimationFrame(gameLoop);
  runCountdown();
  if (fsP && typeof fsP.then === 'function') fsP.then(function () { settleFullscreenLayout(); });
  else settleFullscreenLayout();
}
